/**
 * ServiceList Service - Reactive service list data management
 * Handles querying and pagination of services list (NO selection management).
 *
 * Availability is just part of the query: when the query options carry an
 * `availabilityFilter`, the API layer queries services by real bookable
 * availability (and each service gets an `available` flag); otherwise it runs the
 * plain offset query. The service does not know or care which endpoint is used —
 * that decision lives in {@link queryServices}.
 */
import { defineService, implementService } from '@wix/services-definitions';
import { SignalsServiceDefinition, } from '@wix/services-definitions/core-services/signals';
import { queryServices, hasActiveAvailabilityFilter, } from '../../api/query-services/index.js';
import { queryCategories, } from '../../api/query-categories/index.js';
import { BookingServiceDefinition } from '../booking/booking.js';
import { BOOKING_APP_ID, DEFAULT_QUERY_LIMIT } from '../constants.js';
/**
 * Service definition for the ServiceList service
 */
export const ServiceListServiceDefinition = defineService('service-list');
/**
 * Implementation of the ServiceList service that manages reactive services list data.
 * This service provides signals for services data, query options, pagination metadata
 * (including hasNext flag), loading state, and error handling.
 * It automatically re-fetches services when query options change.
 *
 * @example
 * ```tsx
 * import { ServiceListService, ServiceListServiceDefinition } from '@wix/bookings/services';
 * import { useService } from '@wix/services-manager-react';
 *
 * function ServicesComponent({ serviceListConfig }) {
 *   return (
 *     <ServiceProvider services={createServicesMap([
 *       [ServiceListServiceDefinition, ServiceListService.withConfig(serviceListConfig)]
 *     ])}>
 *       <ServicesDisplay />
 *     </ServiceProvider>
 *   );
 * }
 *
 * function ServicesDisplay() {
 *   const serviceListService = useService(ServiceListServiceDefinition);
 *   const services = serviceListService.servicesSignal.get();
 *   const isLoading = serviceListService.isLoadingSignal.get();
 *   const error = serviceListService.errorSignal.get();
 *   const hasMore = serviceListService.hasMoreServicesSignal.get();
 *
 *   if (isLoading) return <div>Loading services...</div>;
 *   if (error) return <div>Error: {error}</div>;
 *
 *   return (
 *     <div>
 *       {services.map(service => (
 *         <div key={service._id}>
 *           <h3>{service.name}</h3>
 *           <p>{service.description}</p>
 *         </div>
 *       ))}
 *       {hasMore && (
 *         <button onClick={() => serviceListService.actions.loadMore(10)}>
 *           Load More
 *         </button>
 *       )}
 *     </div>
 *   );
 * }
 * ```
 */
export const ServiceListService = implementService.withConfig()(ServiceListServiceDefinition, ({ getService, config }) => {
    const signalsService = getService(SignalsServiceDefinition);
    const bookingService = getService(BookingServiceDefinition);
    // Default appId to BOOKING_APP_ID if not provided
    const appId = config.options?.appId ?? BOOKING_APP_ID;
    // Check if services are provided (showcase mode vs query mode)
    const hasInitialServices = config.services && config.services.length > 0;
    // Check if categories are provided (from SSR prefetch)
    const hasInitialCategories = config.categories && config.categories.length > 0;
    // Initialize services signal - use empty array if not provided
    const initialServices = config.services || [];
    const servicesSignal = signalsService.signal(initialServices);
    // Build query options from config. The filter/availabilityFilter/sort must
    // be preserved even when services are prefetched (e.g. SSR), so loadMore
    // keeps querying the same way and stays in availability mode. A pure
    // showcase config (services without options) naturally yields just
    // { appId } since these fields are absent.
    const initialQueryOptions = {
        appId,
        filter: config.options?.filter,
        availabilityFilter: config.options?.availabilityFilter,
        sort: config.options?.sort,
    };
    // Initialize paging metadata separately (response data - doesn't trigger effect).
    // Carries either offset (plain mode) or cursor (availability mode).
    const initialPagingMetadata = config.options
        ?.pagingMetadata || {
        limit: DEFAULT_QUERY_LIMIT,
        offset: 0,
        count: initialServices.length,
        hasNext: false,
    };
    // Ensure count and hasNext are set
    if (!initialPagingMetadata.count) {
        initialPagingMetadata.count = initialServices.length;
    }
    if (initialPagingMetadata.hasNext === undefined) {
        initialPagingMetadata.hasNext = false;
    }
    // Query options signal - effect subscribes to this, changes trigger re-fetch
    const queryOptionsSignal = signalsService.signal(initialQueryOptions);
    // Paging metadata signal - updated after fetches, does NOT trigger effect
    const pagingMetadataSignal = signalsService.signal(initialPagingMetadata);
    const isLoadingSignal = signalsService.signal(!hasInitialServices);
    const errorSignal = signalsService.signal(null);
    // Categories signal - initialized from config
    const categoriesSignal = signalsService.signal(config.categories || []);
    // Computed filter options from categories - uses platform-compatible field names
    const filterOptionsSignal = signalsService.computed(() => {
        const categories = categoriesSignal.get();
        if (!categories.length)
            return [];
        return [
            {
                key: 'category',
                label: 'Category',
                type: 'single',
                displayType: 'text',
                // Use the actual API field name for platform Filter compatibility
                fieldName: 'category.id',
                validValues: categories
                    .map((c) => c._id)
                    .filter((id) => Boolean(id)),
                valueFormatter: (id) => {
                    const cat = categories.find((c) => c._id === id);
                    return cat?.name || String(id);
                },
            },
        ];
    });
    // Computed signal for filtered state - checks if queryOptionsSignal.filter has values
    const isFilteredSignal = signalsService.computed(() => {
        const filter = queryOptionsSignal.get().filter;
        if (!filter)
            return false;
        // Check if any field in the filter has a non-null/non-undefined value
        return Object.values(filter).some((value) => {
            if (value === null || value === undefined)
                return false;
            if (Array.isArray(value))
                return value.length > 0;
            if (typeof value === 'object') {
                // Check for operators like $in, $hasSome, etc.
                return Object.values(value).some((v) => v !== null && v !== undefined);
            }
            return true;
        });
    });
    // Computed signal indicating whether an availability filter is currently
    // applied. Reuses the same predicate as the API dispatch so the two can't
    // drift. Exposed for the availability filter UI (follow-up PR).
    const hasAvailabilityFilterSignal = signalsService.computed(() => hasActiveAvailabilityFilter(queryOptionsSignal.get().availabilityFilter));
    // Computed signal for effective filter - combines queryOptions.filter with location from BookingService
    const effectiveFilterSignal = signalsService.computed(() => {
        const filter = queryOptionsSignal.get().filter;
        const selectedLocation = bookingService.location.get();
        const locationId = selectedLocation?._id;
        if (!filter && !locationId) {
            return undefined;
        }
        return {
            ...filter,
            // Add location filter using platform Filter format with $hasSome operator
            ...(locationId
                ? { 'locations.business.id': { $hasSome: [locationId] } }
                : {}),
        };
    });
    // Initial fetch - runs once on client when no prefetched data.
    // Fetches both services AND categories in parallel.
    if (typeof window !== 'undefined' && !hasInitialServices) {
        const options = queryOptionsSignal.peek();
        isLoadingSignal.set(true);
        Promise.allSettled([
            queryServices({
                appId: options.appId,
                filter: effectiveFilterSignal.peek(),
                availabilityFilter: options.availabilityFilter,
                pagingMetadata: {
                    limit: pagingMetadataSignal.peek().limit,
                    offset: 0,
                },
                sort: options.sort,
            }),
            !hasInitialCategories ? queryCategories() : Promise.resolve(null),
        ])
            .then(([servicesSettled, categoriesSettled]) => {
            if (servicesSettled.status === 'fulfilled') {
                servicesSignal.set(servicesSettled.value.services);
                pagingMetadataSignal.set(servicesSettled.value.pagingMetadata);
            }
            else {
                errorSignal.set(servicesSettled.reason instanceof Error
                    ? servicesSettled.reason.message
                    : 'Unknown error');
            }
            if (categoriesSettled.status === 'fulfilled' &&
                categoriesSettled.value) {
                categoriesSignal.set(categoriesSettled.value.categories);
            }
            // If categories fail, silently keep empty categories — filter won't be shown
        })
            .finally(() => {
            isLoadingSignal.set(false);
        });
    }
    // Re-fetch when query options or the effective filter (filter + location) change.
    if (typeof window !== 'undefined') {
        let isFirstEffectRun = true;
        signalsService.effect(async () => {
            // Read both signals to establish dependencies.
            const options = queryOptionsSignal.get();
            const effectiveFilter = effectiveFilterSignal.get();
            // Skip first run - initial fetch is handled separately above.
            if (isFirstEffectRun) {
                isFirstEffectRun = false;
                return;
            }
            try {
                isLoadingSignal.set(true);
                servicesSignal.set([]);
                errorSignal.set(null);
                // Reset to the first page when query options change.
                const result = await queryServices({
                    appId: options.appId,
                    filter: effectiveFilter,
                    availabilityFilter: options.availabilityFilter,
                    pagingMetadata: {
                        limit: pagingMetadataSignal.peek().limit,
                        offset: 0,
                    },
                    sort: options.sort,
                });
                servicesSignal.set(result.services);
                pagingMetadataSignal.set(result.pagingMetadata);
            }
            catch (error) {
                errorSignal.set(error instanceof Error ? error.message : 'Unknown error');
            }
            finally {
                isLoadingSignal.set(false);
            }
        });
    }
    const loadMore = async (count) => {
        const options = queryOptionsSignal.peek();
        const currentPaging = pagingMetadataSignal.peek();
        try {
            isLoadingSignal.set(true);
            errorSignal.set(null);
            const result = await queryServices({
                appId: options.appId,
                filter: effectiveFilterSignal.peek(),
                availabilityFilter: options.availabilityFilter,
                pagingMetadata: {
                    limit: count ?? currentPaging.limit ?? DEFAULT_QUERY_LIMIT,
                    // Offset (plain mode) and cursor (availability mode) — queryServices uses what it needs.
                    offset: servicesSignal.peek().length,
                    cursor: currentPaging.cursor,
                },
                sort: options.sort,
            });
            servicesSignal.set([...servicesSignal.get(), ...result.services]);
            pagingMetadataSignal.set(result.pagingMetadata);
        }
        catch (error) {
            errorSignal.set(error instanceof Error ? error.message : 'Unknown error');
        }
        finally {
            isLoadingSignal.set(false);
        }
    };
    return {
        servicesSignal,
        queryOptionsSignal,
        pagingMetadataSignal,
        isLoadingSignal,
        errorSignal,
        categoriesSignal,
        filterOptionsSignal,
        isFilteredSignal,
        hasAvailabilityFilterSignal,
        effectiveFilterSignal,
        actions: {
            loadMore,
            setQueryOptions: (options) => {
                // Reset services and paging when query options change.
                servicesSignal.set([]);
                pagingMetadataSignal.set({
                    limit: pagingMetadataSignal.get().limit || DEFAULT_QUERY_LIMIT,
                    offset: 0,
                    count: 0,
                    hasNext: false,
                    cursor: undefined,
                });
                queryOptionsSignal.set(options);
            },
            setFilter: (filter) => {
                queryOptionsSignal.set({ ...queryOptionsSignal.get(), filter });
            },
            resetFilter: () => {
                queryOptionsSignal.set({
                    ...queryOptionsSignal.get(),
                    filter: undefined,
                });
            },
            resetFilterField: (fieldName) => {
                const newFilter = { ...(queryOptionsSignal.get().filter || {}) };
                delete newFilter[fieldName];
                queryOptionsSignal.set({
                    ...queryOptionsSignal.get(),
                    filter: Object.keys(newFilter).length > 0 ? newFilter : undefined,
                });
            },
        },
        hasMoreServicesSignal: signalsService.computed(() => pagingMetadataSignal.get().hasNext ?? false),
    };
});
/**
 * Loads service list configuration for SSR, pre-fetching services and categories.
 * Pass an `availabilityFilter` to query availability-aware services.
 *
 * @param options - Query options.
 * @returns A success result with the config, or an error result.
 *
 * @example
 * ```ts
 * // Plain offset query
 * const result = await loadServiceListServiceInitialData({
 *   appId: '13d21c63-b5ec-5912-8397-c3a5ddb27a97',
 *   pagingMetadata: { limit: 20, offset: 0 },
 * });
 *
 * // Availability-aware query (cursor paging + `available` flag)
 * const availabilityResult = await loadServiceListServiceInitialData({
 *   availabilityFilter: {
 *     localStartDate: '2026-06-01T09:00:00',
 *     localEndDate: '2026-06-07T17:00:00',
 *     timeZone: 'America/New_York',
 *   },
 *   pagingMetadata: { limit: 20 },
 * });
 * ```
 */
export async function loadServiceListServiceInitialData(options) {
    try {
        const appId = options.appId ?? BOOKING_APP_ID;
        // Fetch services and categories in parallel; categories failure is non-fatal.
        // queryServices picks the endpoint by the presence of availabilityFilter.
        const [servicesResult, categoriesResult] = await Promise.all([
            queryServices({
                appId,
                filter: options.filter,
                pagingMetadata: options.pagingMetadata,
                sort: options.sort,
                availabilityFilter: options.availabilityFilter,
            }),
            queryCategories().catch(() => null),
        ]);
        return {
            type: 'success',
            config: {
                services: servicesResult.services,
                categories: categoriesResult?.categories ?? [],
                options: {
                    appId,
                    filter: options.filter,
                    sort: options.sort,
                    availabilityFilter: options.availabilityFilter,
                    pagingMetadata: servicesResult.pagingMetadata,
                },
            },
        };
    }
    catch (error) {
        console.error('Failed to load service list config:', error);
        return {
            type: 'error',
            error: error instanceof Error ? error : new Error('Unknown error'),
        };
    }
}
